<style>
.data-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.data-heading h1{font-size:clamp(1.8rem,4vw,2.7rem);margin:0}.data-kicker{font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:#236c61}.data-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.data-button{display:inline-flex;align-items:center;justify-content:center;padding:10px 16px;border:1px solid #b5cec7;border-radius:9px;background:#fff;color:#164e43;text-decoration:none;font-weight:650}.data-button.primary{background:#176c55;color:white;border-color:#176c55}.data-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.data-filters label{font-weight:650;font-size:.9rem}.data-filters select,.data-filters input{width:100%;min-height:46px;border:1px solid #b5cec7;border-radius:8px;background:#fff;color:#173d37}.data-filters .wide{grid-column:1/-1}.data-facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.data-facts article{background:#f2f8f5;padding:18px;border:1px solid #d5e4df;border-radius:10px}.data-facts h3{font-size:.9rem;margin:0 0 8px}.data-facts strong{font-size:1.6rem;display:block}.data-facts p{margin:6px 0}.data-table{min-width:660px}.data-table th{font-size:.85rem;background:#f0f6f3}.data-table td{vertical-align:top}.data-code{font-size:.75rem;color:#64746f;display:block;overflow-wrap:anywhere}.data-note{font-size:.9rem;color:#536963}.data-empty{padding:24px;background:#f4f6f5;border-radius:10px}.data-search{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.data-search input{max-width:400px;border:1px solid #b5cec7;border-radius:8px}.data-history{padding:16px 0;border-bottom:1px solid #d5e4df}.data-history p{margin:4px 0}.data-warning{padding:14px;border-left:4px solid #ae780c;background:#fff8e8}.data-errors{padding:16px;background:#fff0ee;border:1px solid #edc4bc;border-radius:8px}.data-field-table{table-layout:fixed}.data-field-table th:first-child{width:42%}.data-field-table td{overflow-wrap:anywhere}.data-auth{max-width:560px;margin:30px auto}.data-auth form{display:grid;gap:14px}.data-auth input,.data-edit input,.data-edit select,.data-edit textarea{border:1px solid #b5cec7;border-radius:8px;width:100%}.data-edit{display:grid;gap:14px;max-width:760px}.data-edit label{font-weight:650}.data-review{padding:20px;border:1px solid #d5e4df;border-radius:10px;margin:20px 0}.data-review form{display:grid;gap:12px}.data-review textarea{width:100%}.data-account{font-size:.9rem}.data-inline{display:inline}.data-inline button{font-size:.85rem;padding:7px 12px}.data-record-link{font-weight:700}.data-chip{display:inline-block;font-size:.75rem;padding:2px 7px;background:#edf4ef;border-radius:5px;margin-top:4px}
.inline-correction summary{cursor:pointer;color:#176c55;font-weight:700}.inline-correction[open]{min-width:260px;max-width:420px}.inline-correction .data-edit{padding:12px;margin-top:8px;border:1px solid #d5e4df;border-radius:10px;background:#f7faf8}.inline-correction label{font-size:.85rem}.inline-correction input,.inline-correction select,.inline-correction textarea{box-sizing:border-box;padding:8px;max-width:100%}</style>
